const known = (ctx, columns, c, arg) => {
  if (c in columns) return true;
  ctx.error("T002", `no column '${c}' at this step.${didYouMean(c, Object.keys(columns))}`, { tip: `columns: ${Object.keys(columns).join(", ")}`, arg, suggest: Object.keys(columns) });
